{"source":"def investigate(context, acquire):
    receipts = context.get('receipts') or []
    seen = set()
    for row in receipts:
        query = row.get('query') if isinstance(row, dict) else None
        if isinstance(query, dict):
            actions = query.get('actions')
            if isinstance(actions, list):
                seen.add(tuple((a.get('op'), a.get('id')) for a in actions if isinstance(a, dict)))
    actions = [
        {'op': 'put', 'id': 5},
        {'op': 'begin'},
        {'op': 'put', 'id': 9},
        {'op': 'rollback'},
        {'op': 'put', 'id': 2}
    ]
    key = tuple((a['op'], a.get('id')) for a in actions)
    if key in seen:
        return {'query': None, 'note': {'status': 'duplicate', 'chosen': key}}
    return {'query': {'actions': actions}, 'note': {'hypothesis': 'AUTOINCREMENT sqlite_sequence is not rolled back; parent restores high=5 and predicts 6, native likely predicts 10'}}
","scope":"Compare parent's rollback-restored max model against SQLite AUTOINCREMENT persistence. The parent saves and restores high on rollback, so after put 5, begin, put 9, rollback it predicts 6. SQLite keeps the allocated sqlite_sequence high-water mark even when the transaction is rolled back, so the next implicit ID should be 10.","change":"Use a rollback that hides a larger inserted ID, then insert a smaller ID outside the transaction. This isolates whether the native allocator retains rolled-back maxima rather than recomputing from visible rows."}
